create table if not exists habitflow.habits(id uuid primary key,user_id uuid references habitflow.users(id),name varchar(120) not null,color varchar(20) not null,category varchar(80),is_archived boolean default false,archived_at timestamp null,created_at timestamp not null,updated_at timestamp not null);
create table if not exists habitflow.habit_completions(id uuid primary key,habit_id uuid references habitflow.habits(id),user_id uuid references habitflow.users(id),completed_date date not null,created_at timestamp not null,unique(habit_id, completed_date));
